/* Interactive pathway exploration and a layout-controlled PNG export. */
function schoolPicker(c){return c.options?`<label class="provider-label">Take this class at<select data-provider="${esc(c.code)}" aria-label="School for ${esc(c.displayCode||c.code)}">${c.options.map(o=>`<option value="${esc(o.institution)}" ${o.institution===c.institution?'selected':''}>${esc(o.institution)} · ${esc(o.code)} · ${o.credits} credits</option>`).join('')}</select></label>${c.options.length===1?'<small class="provider-limit">Only this school has a verified option in Camino.</small>':''}`:''}
function plannerLab(plan){
 const total=plan.courses.length?Math.max(...plan.courses.map(c=>c.term))+1:0;
 caminoViewedTerm=Math.min(Math.max(0,caminoViewedTerm),Math.max(0,total-1));
 const current=plan.courses.filter(c=>c.term===caminoViewedTerm);
 const variants=[['No summers',false,mode],['A gentler climb',!!state.profile?.summer,'Flexible'],['Pick up the pace',true,'Accelerated']];
 return `<section class="planner-lab"><div class="lab-horizon">${caminoWorld(Math.max(6,total))}<div class="lab-intro"><span class="tag">THE CAMINO STAIRWAY</span><h2>Big futures.<br><em>Small steps.</em></h2><p>Build on what you know. One course, one quarter, one step closer.</p><button class="motion-control" data-toggle-motion>${state.reduceMotion?'Enable motion':'Pause motion'} ◉</button><p class="climb-status">Exploring step ${total?caminoViewedTerm+1:0} of ${total} · Your roadmap, not a completion record.</p></div></div><div class="lab-workspace"><div class="row"><div><span class="tag">YOUR STAIRWAY / QUARTER BY QUARTER</span><h2>Choose your next step.</h2></div><button class="btn" id="export-image-top">Save as image ↓</button></div><p>Select a quarter to climb the stairway. Change the school on any class with a published alternative.</p><div class="stair-quarters" role="group" aria-label="Explore quarters">${Array.from({length:total},(_,i)=>`<button class="quarter-step ${i===caminoViewedTerm?'active':''} ${i<caminoViewedTerm?'visited':''}" data-climb-term="${i}" data-from-term="${caminoViewedTerm}" aria-pressed="${i===caminoViewedTerm}"><span>${String(i+1).padStart(2,'0')}</span><strong>${termName(i)}</strong></button>`).join('')}</div><section class="selected-landing" data-selected-landing tabindex="-1" aria-label="Selected quarter"><div class="row"><div><span class="tag">LANDING ${caminoViewedTerm+1}</span><h3>${total?termName(caminoViewedTerm):'Your next chapter'}</h3></div><span class="badge">${current.reduce((n,c)=>n+c.credits,0)} credits</span></div><div class="landing-courses">${current.map(c=>`<article class="landing-course"><button class="map-node ${c.institution===AcademicPathway.BC?'bellevue':''}" data-map-code="${esc(c.code)}" aria-pressed="false"><small>${esc(c.institution)}</small><strong>${esc(c.displayCode||c.code)}</strong><span>${esc(c.title)}</span><span class="step-discover">See how this step connects ↗</span></button>${schoolPicker(c)}</article>`).join('')||'<p>No courses placed in this quarter.</p>'}</div><div class="climb-controls"><button class="btn" data-climb-term="${Math.max(0,caminoViewedTerm-1)}" data-from-term="${caminoViewedTerm}" ${caminoViewedTerm===0?'disabled':''}>← Previous step</button><button class="btn primary" data-climb-term="${Math.min(total-1,caminoViewedTerm+1)}" data-from-term="${caminoViewedTerm}" ${caminoViewedTerm>=total-1?'disabled':''}>Climb to next quarter ↗</button></div></section><div id="map-detail" class="map-detail" aria-live="polite">Choose a course to see what it builds on and what it unlocks.</div><div class="row"><h3>Find your pace.</h3><label><input id="lab-summer" type="checkbox" ${state.profile?.summer?'checked':''}> Include summer quarters</label></div><label><input id="lab-bellevue" type="checkbox" ${state.profile?.bellevueScience!==false?'checked':''}> Prefer Bellevue for physics and programming</label><div class="what-if-grid">${variants.map(([label,summer,load],i)=>{const p=AcademicPathway.plan({...state,profile:{...state.profile,summer}},load);const count=p.courses.length?Math.max(...p.courses.map(c=>c.term))+1:0;return `<div><div class="pace-stairs" aria-hidden="true"><i></i><i></i><i></i></div><strong>${label}</strong><span>${count} planned quarters · ${p.blocked.length} unplaced</span><button class="chip" data-try-load="${load}" data-summer="${summer}">Try this pace</button></div>`}).join('')}</div><p class="muted">Exploring steps does not mark courses complete. Future offerings and graduation dates need confirmation.</p></div></section>`;
}
function bindPlannerLab(){
 const apply=(key,value)=>{if(typeof recordPlanChange==='function')recordPlanChange('Scheduling preference '+key+' updated. Future quarters recalculated; academic records retained.');state.profile||={};state.profile[key]=value;state.manual=null;save();render()};
 document.querySelector('#lab-summer')?.addEventListener('change',e=>apply('summer',e.target.checked));
 document.querySelector('#lab-bellevue')?.addEventListener('change',e=>{state.courseProviders||={};for(const code of ['B PHYS 121','B PHYS 122','B PHYS 123','CSS 142','CSS 143'])delete state.courseProviders[code];apply('bellevueScience',e.target.checked)});
 document.querySelectorAll('[data-try-load]').forEach(el=>el.onclick=()=>{mode=el.dataset.tryLoad;state.profile||={};state.profile.load=mode;apply('summer',el.dataset.summer==='true')});
 document.querySelectorAll('[data-map-code]').forEach(el=>el.onclick=()=>{const course=currentPlan.find(c=>c.code===el.dataset.mapCode),ancestors=new Set(),next=new Set();const walk=(code,reverse,seen)=>{if(seen.has(code))return;seen.add(code);for(const c of currentPlan){if(reverse?c.code===code:false)for(const p of c.prereqs)walk(p,true,seen);if(!reverse&&c.prereqs.includes(code))walk(c.code,false,seen)}};walk(course.code,true,ancestors);walk(course.code,false,next);document.querySelectorAll('[data-map-code]').forEach(n=>{n.classList.toggle('related',ancestors.has(n.dataset.mapCode)||next.has(n.dataset.mapCode));n.classList.toggle('selected',n.dataset.mapCode===course.code);n.setAttribute('aria-pressed',String(n.dataset.mapCode===course.code))});document.querySelector('#map-detail').innerHTML=`<strong>${esc(course.displayCode||course.code)} · ${esc(course.title)}</strong><p>${esc(course.explanation||'Scheduled from your entered prerequisites.')}</p><span>Unlocks: ${esc(currentPlan.filter(c=>c.prereqs.includes(course.code)).map(c=>c.displayCode||c.code).join(', ')||'No further course in this roadmap')}</span>`});
 for(const id of ['#export-image','#export-image-top'])document.querySelector(id)?.addEventListener('click',downloadPlanImage);
}
function downloadPlanImage(options){
 const plan=Array.isArray(options?.courses)?options.courses:currentPlan,imageProfile=options?.profile||state.profile;
 if(!plan?.length)return toast('Build a plan with courses first.');
 const width=1600,pad=64,gap=24,cols=3,cardW=(width-pad*2-gap*(cols-1))/cols,terms=Math.max(...plan.map(c=>c.term))+1;
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');if(!ctx)return toast('Image export is unavailable in this browser. Download the plan data instead.');
 function wrap(text,max,font){ctx.font=font;const lines=[];let line='';for(const word of String(text).split(/\s+/)){if(ctx.measureText(word).width>max){if(line){lines.push(line);line=''}let chunk='';for(const char of word){if(chunk&&ctx.measureText(chunk+char).width>max){lines.push(chunk);chunk=char}else chunk+=char}line=chunk;continue}const next=line?line+' '+word:word;if(ctx.measureText(next).width>max&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);return lines;}
 const cards=Array.from({length:terms},(_,term)=>{const courses=plan.filter(c=>c.term===term);return{term,courses,heights:courses.map(c=>76+wrap(c.title,cardW-40,'20px Arial').length*25+wrap(c.institution,cardW-40,'17px Arial').length*22)}});
 const rows=Array.from({length:Math.ceil(terms/cols)},(_,i)=>Math.max(...cards.slice(i*cols,i*cols+cols).map(c=>100+c.heights.reduce((a,b)=>a+b,0))));
 const titleLines=wrap(imageProfile?.major||'Your academic plan',width-pad*2,'bold 42px Arial'),targetLines=wrap(imageProfile?.target||'Personal course roadmap',width-pad*2,'24px Arial'),headerHeight=160+titleLines.length*50+targetLines.length*30,footerLines=wrap(imageProfile?.exportNote||'Future offerings, enrollment prerequisites and full degree requirements require confirmation.',width-pad*2,'19px Arial'),checkpoints=options?.checkpoints||state.advisingDates||[],checkpointLines=checkpoints.flatMap(d=>wrap(d.date+' · '+d.label+' · '+d.institution+' · '+d.cycle+(' · '+(typeof DeadlineCore!=='undefined'?DeadlineCore.basisLabel(d):d.dateBasis?'Source-backed date — confirm basis':'Entered reminder')),width-pad*2,'19px Arial'));canvas.width=width;canvas.height=headerHeight+rows.reduce((a,b)=>a+b+gap,0)+footerLines.length*25+checkpointLines.length*26+(checkpoints.length?90:0)+110;ctx.fillStyle='#100e20';ctx.fillRect(0,0,width,canvas.height);
 const text=(str,x,y,font,color)=>{ctx.font=font;ctx.fillStyle=color;ctx.fillText(str,x,y)};
 text('CAMINO / YOUR DIRECTION',pad,55,'bold 20px Arial','#9ce9db');let headingY=108;for(const line of titleLines){text(line,pad,headingY,'bold 42px Arial','#eadfff');headingY+=50}for(const line of targetLines){text(line,pad,headingY,'24px Arial','#c0b0d2');headingY+=30}text(`${mode} · ${imageProfile?.summer?'Summer included':'No summer'} · ${terms} planned ${imageProfile?.calendar==='Semester'?'semesters':'quarters'} · Draft for advisor review`,pad,headingY+12,'20px Arial','#c0b0d2');
 let y=headerHeight;rows.forEach((height,row)=>{cards.slice(row*cols,row*cols+cols).forEach((card,col)=>{const x=pad+col*(cardW+gap);ctx.fillStyle='#262038';ctx.fillRect(x,y,cardW,height);text(ProductCore.termName(imageProfile,card.term),x+20,y+37,'bold 24px Arial','#eadfff');text(card.courses.reduce((n,c)=>n+c.credits,0)+(imageProfile?.calendar==='Semester'?' semester credits':' quarter credits'),x+20,y+68,'18px Arial','#baadca');let cy=y+100;card.courses.forEach((c,i)=>{text(c.displayCode||c.code,x+20,cy,'bold 22px Arial',c.institution===AcademicPathway.BC?'#9ce9db':'#eadfff');let lineY=cy+29;for(const line of wrap(c.title,cardW-40,'20px Arial')){text(line,x+20,lineY,'20px Arial','#e5d9f0');lineY+=25}for(const line of wrap(c.institution,cardW-40,'17px Arial')){text(line,x+20,lineY+4,'17px Arial','#baadca');lineY+=22}text(c.credits+' credits',x+20,lineY+8,'17px Arial','#baadca');cy+=card.heights[i]})});y+=height+gap});
 if(checkpoints.length){text('APPLICATION & GRADUATION CHECKPOINTS',pad,y+30,'bold 20px Arial','#9ce9db');y+=66;for(const line of checkpointLines){text(line,pad,y,'19px Arial','#eadfff');y+=26}y+=20}for(const line of footerLines){text(line,pad,y+25,'19px Arial','#baadca');y+=25}text('Generated '+new Date().toLocaleDateString('en-US',{timeZone:'America/Los_Angeles'})+' • Dates are planning reminders; verify the source and closing time.',pad,y+58,'18px Arial','#baadca');
 canvas.toBlob(blob=>{if(!blob)return toast('Image export failed. Please try again.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='camino-course-plan.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},'image/png');
}
